package com.ml.tblandroidtxt;
import org.json.JSONArray;import org.json.JSONObject;
/** Evidence created in a fresh L3 context before REPORT_L1 is unlocked. */
public final class EditorialL3IndependentContract {
 public static String schema(){return "{\"chapterId\":\"string\",\"scenes\":[{\"id\":\"string\",\"rawStart\":\"anchor\",\"rawEnd\":\"anchor\",\"coverage\":\"ALIGNED|MISSING|EXTRA|MISALIGNED\",\"fidelity\":\"CLOSED\",\"voice\":\"CLOSED\",\"status\":\"CLOSED\"}],\"issues\":[{\"id\":\"string\",\"rawAnchor\":\"string\",\"viAnchor\":\"string\",\"finding\":\"string\",\"impact\":\"string\"}],\"crossSceneVoiceAudit\":\"CLOSED\",\"status\":\"CLOSED\"}";}
 public static String validate(String text,String chapterId){try{JSONObject r=new JSONObject(text);if(!chapterId.equals(r.optString("chapterId")))return "L3 independent chapterId mismatch";JSONArray scenes=r.optJSONArray("scenes");if(scenes==null||scenes.length()==0)return "L3 independent ledger requires scenes";for(int i=0;i<scenes.length();i++){JSONObject s=scenes.optJSONObject(i);if(s==null||blank(s.optString("id"))||blank(s.optString("rawStart"))||blank(s.optString("rawEnd"))||!one(s.optString("coverage"),"ALIGNED","MISSING","EXTRA","MISALIGNED")||!"CLOSED".equals(s.optString("fidelity"))||!"CLOSED".equals(s.optString("voice"))||!"CLOSED".equals(s.optString("status")))return "L3 independent scene is incomplete";}JSONArray issues=r.optJSONArray("issues");if(issues==null)return "Missing L3 independent issues";for(int i=0;i<issues.length();i++){JSONObject x=issues.optJSONObject(i);if(x==null||blank(x.optString("id"))||blank(x.optString("rawAnchor"))||blank(x.optString("viAnchor"))||blank(x.optString("finding"))||blank(x.optString("impact")))return "L3 independent issue is incomplete";}if(!"CLOSED".equals(r.optString("crossSceneVoiceAudit"))||!"CLOSED".equals(r.optString("status")))return "L3 independent audit is not closed";return null;}catch(Exception e){return "Invalid L3 independent JSON";}}
 private static boolean blank(String x){return x==null||x.trim().isEmpty();}private static boolean one(String x,String...a){for(String y:a)if(y.equals(x))return true;return false;}private EditorialL3IndependentContract(){}
}
